import React, { useState, useMemo } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import authService from '../services/authService';
import { Eye, EyeOff, MapPin, ShieldCheck } from 'lucide-react';

const PHILIPPINE_REGIONS = [
    { label: 'NCR - National Capital Region', code: '1300000000' },
    { label: 'CAR - Cordillera Administrative Region', code: '1400000000' },
    { label: 'Region I - Ilocos Region', code: '0100000000' },
    { label: 'Region II - Cagayan Valley', code: '0200000000' },
    { label: 'Region III - Central Luzon', code: '0300000000' },
    { label: 'Region IV-A - CALABARZON', code: '0400000000' },
    { label: 'MIMAROPA Region', code: '1700000000' },
    { label: 'Region V - Bicol Region', code: '0500000000' },
    { label: 'Region VI - Western Visayas', code: '0600000000' },
    { label: 'Negros Island Region (NIR)', code: '1800000000' },
    { label: 'Region VII - Central Visayas', code: '0700000000' },
    { label: 'Region VIII - Eastern Visayas', code: '0800000000' },
    { label: 'Region IX - Zamboanga Peninsula', code: '0900000000' },
    { label: 'Region X - Northern Mindanao', code: '1000000000' },
    { label: 'Region XI - Davao Region', code: '1100000000' },
    { label: 'Region XII - SOCCSKSARGEN', code: '1200000000' },
    { label: 'Region XIII - Caraga', code: '1600000000' },
    { label: 'BARMM - Bangsamoro Autonomous Region in Muslim Mindanao', code: '1900000000' },
];

export default function Register() {
    const [formData, setFormData] = useState({
        name: '',
        email: '',
        password: '',
        passwordConfirmation: '',
        phone: '',
        address: '',
        city: '',
        region: '',
        region_code: '',
        postal_code: '',
    });
    const [fieldErrors, setFieldErrors] = useState({});
    const [generalError, setGeneralError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    const [loading, setLoading] = useState(false);
    const [googleLoading, setGoogleLoading] = useState(false);
    const [showPassword, setShowPassword] = useState(false);
    const [showPasswordConfirmation, setShowPasswordConfirmation] = useState(false);
    const [verificationPending, setVerificationPending] = useState(false);
    const [resendLoading, setResendLoading] = useState(false);
    const [resendMessage, setResendMessage] = useState('');
    const [resendError, setResendError] = useState('');
    const [touched, setTouched] = useState({});
    const { register } = useAuth();
    const navigate = useNavigate();

    // Password strength indicator
    const passwordStrength = useMemo(() => {
        const pwd = formData.password;
        if (!pwd) return { score: 0, label: '', color: '' };
        
        let score = 0;
        if (pwd.length >= 8) score++;
        if (pwd.length >= 12) score++;
        if (/[a-z]/.test(pwd) && /[A-Z]/.test(pwd)) score++;
        if (/\d/.test(pwd)) score++;
        if (/[^a-zA-Z\d]/.test(pwd)) score++;

        const strengthLevels = {
            1: { label: 'Weak', color: 'text-danger' },
            2: { label: 'Fair', color: 'text-warning' },
            3: { label: 'Good', color: 'text-info' },
            4: { label: 'Strong', color: 'text-success' },
            5: { label: 'Very Strong', color: 'text-success' },
        };

        return { score: Math.min(score, 5), ...strengthLevels[Math.min(score, 5)] } || {};
    }, [formData.password]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        setVerificationPending(false);
        // Clear field error when user starts typing
        if (fieldErrors[name]) {
            setFieldErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleRegionChange = (event) => {
        const region = PHILIPPINE_REGIONS.find((item) => item.label === event.target.value);
        setFormData((prev) => ({
            ...prev,
            region: region?.label || '',
            region_code: region?.code || '',
        }));
        setVerificationPending(false);
        if (fieldErrors.region) setFieldErrors((prev) => ({ ...prev, region: '' }));
        setTouched((prev) => ({ ...prev, region: true }));
    };

    const handleBlur = (e) => {
        const { name } = e.target;
        setTouched(prev => ({ ...prev, [name]: true }));
    };

    const validateForm = () => {
        const errors = {};
        
        if (!formData.name.trim()) {
            errors.name = 'Full name is required';
        }
        
        if (!formData.email.trim()) {
            errors.email = 'Email is required';
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
            errors.email = 'Please enter a valid email address';
        }
        
        if (!formData.password) {
            errors.password = 'Password is required';
        } else if (formData.password.length < 8) {
            errors.password = 'Password must be at least 8 characters';
        }
        
        if (formData.password !== formData.passwordConfirmation) {
            errors.passwordConfirmation = 'Passwords do not match';
        }

        setFieldErrors(errors);
        return Object.keys(errors).length === 0;
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setGeneralError('');
        setSuccessMessage('');

        if (!validateForm()) {
            return;
        }

        setLoading(true);

        try {
            const result = await register({
                name: formData.name,
                email: formData.email,
                password: formData.password,
                password_confirmation: formData.passwordConfirmation,
                phone: formData.phone || null,
                address: formData.address || null,
                city: formData.city || null,
                region: formData.region || null,
                region_code: formData.region_code || null,
                postal_code: formData.postal_code || null,
            });

            if (result?.requires_email_verification === true) {
                setVerificationPending(true);
                setSuccessMessage(result.message || `We sent a verification link to ${formData.email}. Open it to verify your address before signing in.`);
                return;
            }

            setSuccessMessage('Account created successfully! Redirecting to login...');
            setTimeout(() => {
                navigate('/login');
            }, 2000);
        } catch (err) {
            const backendErrors = err.response?.data?.errors || {};
            const normalizedErrors = Object.fromEntries(
                Object.entries(backendErrors).map(([field, messages]) => [field === 'region_code' ? 'region' : field, Array.isArray(messages) ? messages[0] : messages])
            );
            if (Object.keys(normalizedErrors).length > 0) {
                setFieldErrors((prev) => ({ ...prev, ...normalizedErrors }));
            }
            const validationMessage = Object.values(backendErrors).flat()[0];
            const errorMsg = err.response?.data?.message
                || err.response?.data?.error
                || validationMessage
                || (!err.response
                    ? 'Could not reach the signup service. Check that the server is running and try again.'
                    : 'We could not create your account right now. Please try again shortly.');
            setGeneralError(errorMsg);
        } finally {
            setLoading(false);
        }
    };

    const handleGoogleSignup = async () => {
        setGoogleLoading(true);
        setGeneralError('');
        let shouldResetLoading = true;

        try {
            const redirectTo = `${window.location.origin}/auth/callback`;
            const response = await authService.getSocialAuthUrl('google', redirectTo);
            const authUrl = response?.data?.url;

            if (authUrl) {
                shouldResetLoading = false;
                window.location.href = authUrl;
                return;
            }

            setGeneralError('Google authentication configuration error. Please try email signup or contact support.');
        } catch (err) {
            const errorMessage = err.response?.data?.message
                || err.message
                || 'Failed to connect to Google. Please check your connection and try again.';
            setGeneralError(errorMessage);
            console.error('Google signup error:', err);
        } finally {
            if (shouldResetLoading) {
                setGoogleLoading(false);
            }
        }
    };

    const handleResendVerification = async () => {
        setResendLoading(true);
        setResendMessage('');
        setResendError('');
        try {
            const response = await authService.resendVerification({
                email: formData.email,
                password: formData.password,
            });
            setResendMessage(response?.data?.message || 'If this account needs verification, a fresh link has been sent. Check your inbox and spam folder.');
        } catch {
            setResendError('We could not request a new verification email. Please try again in a moment.');
        } finally {
            setResendLoading(false);
        }
    };

    return (
        <div className="auth-page auth-page--signup">
            <div className="auth-container auth-container--wide auth-signup-layout">
                <aside className="signup-brand-panel" aria-label="About the CarVex marketplace">
                    <Link to="/" className="signup-brand-link" aria-label="CarVex home">
                        <img src="/images/carvex.png" alt="CarVex Auto Supply and Car Accessories" />
                    </Link>
                    <div className="signup-brand-story">
                        <span className="signup-brand-eyebrow">The parts marketplace built for your next drive</span>
                        <h2>Keep your ride moving.</h2>
                        <p>Find the parts you need, connect with local sellers, and keep every trip on track.</p>
                        <ul>
                            <li><span aria-hidden="true">01</span> Discover parts from local shops</li>
                            <li><span aria-hidden="true">02</span> Save your details for faster checkout</li>
                            <li><span aria-hidden="true">03</span> List your inventory when you’re ready</li>
                        </ul>
                    </div>
                    <p className="signup-brand-footnote"><MapPin size={15} aria-hidden="true" /> Made for drivers and sellers in the Philippines</p>
                </aside>
                <section className="auth-modal auth-modal--register" aria-labelledby="register-heading">
                    <header className="auth-modal__header auth-modal__header--register">
                        <button type="button" className="auth-modal__close" aria-label="Close signup" onClick={() => navigate('/')}>
                            <span aria-hidden="true">×</span>
                        </button>
                        <div className="signup-header-content">
                            <span className="signup-badge">WELCOME TO CARVEX</span>
                            <h1 id="register-heading">Create your account</h1>
                            <p className="auth-modal__subtitle">Join the CarVex parts marketplace.</p>
                        </div>
                    </header>

                    <div className="auth-modal__body">
                        {successMessage ? (
                            <div className="signup-alert alert-success" role="status" aria-live="polite">
                                <ShieldCheck size={20} aria-hidden="true" />
                                <div className="alert-content">
                                    <strong>{verificationPending ? 'Verify your email' : 'Success'}</strong>
                                    <p>{successMessage}</p>
                                    {verificationPending ? <small>Check your inbox and spam folder. You can sign in after verifying your address.</small> : null}
                                    {verificationPending ? (
                                        <div className="auth-verification-actions">
                                            <button type="button" onClick={handleResendVerification} disabled={resendLoading}>
                                                {resendLoading ? 'Sending...' : 'Resend verification email'}
                                            </button>
                                            {resendMessage ? <small role="status">{resendMessage}</small> : null}
                                            {resendError ? <small role="alert">{resendError}</small> : null}
                                        </div>
                                    ) : null}
                                </div>
                            </div>
                        ) : null}
                        {generalError ? (
                            <div className="signup-alert alert-error" role="alert">
                                <span className="alert-icon" aria-hidden="true">!</span>
                                <div className="alert-content">
                                    <strong>We couldn't create your account</strong>
                                    <p>{generalError}</p>
                                </div>
                            </div>
                        ) : null}

                        <button
                            type="button"
                            className="btn-signup-google"
                            onClick={handleGoogleSignup}
                            disabled={googleLoading || loading || verificationPending}
                            aria-busy={googleLoading}
                        >
                            {googleLoading ? <span role="status">Connecting to Google...</span> : (
                                <>
                                    <svg className="google-icon" viewBox="0 0 24 24" width="20" height="20" aria-hidden="true">
                                        <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>
                                        <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>
                                        <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z"/>
                                        <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z"/>
                                    </svg>
                                    <span>Continue with Google</span>
                                </>
                            )}
                        </button>

                        <div className="auth-divider"><span>or create an account with email</span></div>

                        <form onSubmit={handleSubmit} className="auth-form auth-form--register" noValidate>
                            <div className="form-group">
                                <label htmlFor="name">Full name <span className="required">*</span></label>
                                <input
                                    id="name"
                                    type="text"
                                    name="name"
                                    className={'form-control' + (fieldErrors.name ? ' is-invalid' : '')}
                                    value={formData.name}
                                    onChange={handleChange}
                                    onBlur={handleBlur}
                                    autoComplete="name"
                                    aria-invalid={Boolean(fieldErrors.name)}
                                    aria-describedby={fieldErrors.name ? 'register-name-error' : undefined}
                                    disabled={loading || googleLoading}
                                />
                                {fieldErrors.name ? <small className="field-error" id="register-name-error">{fieldErrors.name}</small> : null}
                            </div>

                            <div className="form-group">
                                <label htmlFor="email">Email address <span className="required">*</span></label>
                                <input
                                    id="email"
                                    type="email"
                                    name="email"
                                    className={'form-control' + (fieldErrors.email ? ' is-invalid' : '')}
                                    value={formData.email}
                                    onChange={handleChange}
                                    onBlur={handleBlur}
                                    autoComplete="email"
                                    inputMode="email"
                                    aria-invalid={Boolean(fieldErrors.email)}
                                    aria-describedby={fieldErrors.email ? 'register-email-error' : undefined}
                                    disabled={loading || googleLoading}
                                />
                                {fieldErrors.email ? <small className="field-error" id="register-email-error">{fieldErrors.email}</small> : null}
                            </div>

                            <div className="form-group">
                                <label htmlFor="password">Password <span className="required">*</span></label>
                                <div className="auth-password-field">
                                    <input
                                        id="password"
                                        type={showPassword ? 'text' : 'password'}
                                        name="password"
                                        className={'form-control' + (fieldErrors.password ? ' is-invalid' : '')}
                                        value={formData.password}
                                        onChange={handleChange}
                                        onBlur={handleBlur}
                                        autoComplete="new-password"
                                        minLength={8}
                                        aria-invalid={Boolean(fieldErrors.password)}
                                        aria-describedby={fieldErrors.password ? 'register-password-error' : 'register-password-help'}
                                        disabled={loading || googleLoading}
                                    />
                                    <button
                                        type="button"
                                        className="auth-password-toggle auth-password-toggle--icon"
                                        onClick={() => setShowPassword((visible) => !visible)}
                                        aria-label={showPassword ? 'Hide password' : 'Show password'}
                                        aria-pressed={showPassword}
                                    >
                                        {showPassword ? <EyeOff size={17} /> : <Eye size={17} />}
                                    </button>
                                </div>
                                <small className="auth-field-help" id="register-password-help">Use at least 8 characters.</small>
                                {formData.password ? (
                                    <div className="password-strength-indicator" aria-live="polite">
                                        <div className="strength-info">
                                            <span className="strength-label">Password strength</span>
                                            <span className={'strength-value ' + (passwordStrength.color || 'text-muted')}>{passwordStrength.label}</span>
                                        </div>
                                        <div className="strength-bar" aria-hidden="true">
                                            {[...Array(5)].map((_, index) => <span key={index} className={'strength-segment' + (index < passwordStrength.score ? ' filled' : '')} />)}
                                        </div>
                                    </div>
                                ) : null}
                                {fieldErrors.password ? <small className="field-error" id="register-password-error">{fieldErrors.password}</small> : null}
                            </div>

                            <div className="form-group">
                                <label htmlFor="passwordConfirmation">Confirm password <span className="required">*</span></label>
                                <div className="auth-password-field">
                                    <input
                                        id="passwordConfirmation"
                                        type={showPasswordConfirmation ? 'text' : 'password'}
                                        name="passwordConfirmation"
                                        className={'form-control' + (fieldErrors.passwordConfirmation ? ' is-invalid' : '')}
                                        value={formData.passwordConfirmation}
                                        onChange={handleChange}
                                        onBlur={handleBlur}
                                        autoComplete="new-password"
                                        aria-invalid={Boolean(fieldErrors.passwordConfirmation)}
                                        aria-describedby={fieldErrors.passwordConfirmation ? 'register-confirm-error' : undefined}
                                        disabled={loading || googleLoading}
                                    />
                                    <button
                                        type="button"
                                        className="auth-password-toggle auth-password-toggle--icon"
                                        onClick={() => setShowPasswordConfirmation((visible) => !visible)}
                                        aria-label={showPasswordConfirmation ? 'Hide confirmation password' : 'Show confirmation password'}
                                        aria-pressed={showPasswordConfirmation}
                                    >
                                        {showPasswordConfirmation ? <EyeOff size={17} /> : <Eye size={17} />}
                                    </button>
                                </div>
                                {fieldErrors.passwordConfirmation ? <small className="field-error" id="register-confirm-error">{fieldErrors.passwordConfirmation}</small> : null}
                            </div>

                            <div className="auth-form-section">
                                <div className="auth-form-section__heading">
                                    <MapPin size={16} aria-hidden="true" />
                                    <span>Delivery details <small>Optional</small></span>
                                </div>
                                <div className="form-row--two">
                                    <div className="form-group">
                                        <label htmlFor="phone">Phone number</label>
                                        <input id="phone" type="tel" name="phone" className="form-control" value={formData.phone} onChange={handleChange} onBlur={handleBlur} autoComplete="tel" inputMode="tel" disabled={loading || googleLoading} />
                                    </div>
                                    <div className="form-group">
                                        <label htmlFor="city">City / municipality</label>
                                        <input id="city" type="text" name="city" className="form-control" value={formData.city} onChange={handleChange} onBlur={handleBlur} autoComplete="address-level2" disabled={loading || googleLoading} />
                                    </div>
                                </div>
                                <div className="form-group">
                                    <label htmlFor="address">Street address</label>
                                    <input id="address" type="text" name="address" className="form-control" value={formData.address} onChange={handleChange} onBlur={handleBlur} autoComplete="street-address" disabled={loading || googleLoading} />
                                </div>
                                <div className="form-row--two">
                                    <div className="form-group">
                                        <label htmlFor="region">Region</label>
                                        <select id="region" name="region" className={'form-control' + (fieldErrors.region ? ' is-invalid' : '')} value={formData.region} onChange={handleRegionChange} onBlur={handleBlur} autoComplete="address-level1" disabled={loading || googleLoading} aria-invalid={Boolean(fieldErrors.region)} aria-describedby={fieldErrors.region ? 'register-region-error' : undefined}>
                                            <option value="">Choose a region</option>
                                            {PHILIPPINE_REGIONS.map((region) => <option key={region.code} value={region.label}>{region.label}</option>)}
                                        </select>
                                        {fieldErrors.region ? <small className="field-error" id="register-region-error">{fieldErrors.region}</small> : null}
                                    </div>
                                    <div className="form-group">
                                        <label htmlFor="postal_code">Postal code</label>
                                        <input id="postal_code" type="text" name="postal_code" className="form-control" value={formData.postal_code} onChange={handleChange} onBlur={handleBlur} autoComplete="postal-code" inputMode="numeric" disabled={loading || googleLoading} />
                                    </div>
                                </div>
                            </div>

                            <button type="submit" className="btn-signup-submit" disabled={loading || googleLoading || verificationPending} aria-busy={loading}>
                                {loading ? 'Creating account...' : verificationPending ? 'Verification email sent' : 'Create account'}
                            </button>
                        </form>

                        <div className="auth-footer">
                            <p>Already have an account? <Link to="/login" className="auth-link-primary">Sign in</Link></p>
                        </div>
                        <p className="signup-privacy-notice">
                            By creating an account, you agree to our <Link to="/terms">Terms of Service</Link> and <Link to="/privacy">Privacy Policy</Link>.
                        </p>
                    </div>
                </section>
            </div>
        </div>
    );
}
